python3 - <<'EOF'
import json

# Load all definitions
def_map = {}
for f, k in [('/tmp/def_decision.json','decision'),('/tmp/def_terminate.json','terminate'),('/tmp/def_script.json','script'),('/tmp/def_end.json','end')]:
    with open(f) as fp:
        def_map[k] = json.load(fp)['Data']['Node']

# Read existing flow (has start + createContact1 nodes + their definitions)
with open('/work/output/artifacts/skill-flow-ipe-multiselect/MultiselectTest/MultiselectTest/MultiselectTest.flow') as fp:
    flow = json.load(fp)

# --- Add user-owned nodes ---
# Decision node: check if createContact1.output has an id (success indicator)
flow['nodes'].append({
    "id": "checkSuccess",
    "type": "core.logic.decision",
    "typeVersion": "1.1",
    "display": {"label": "Call succeeded?"},
    "inputs": {
        "expression": "$vars.createContact1.output != null && $vars.createContact1.output.id != null",
        "trueLabel": "Yes",
        "falseLabel": "No"
    }
})

# Script node: log "Multiselect test passed"
flow['nodes'].append({
    "id": "logPassed",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Log passed"},
    "inputs": {
        "script": "return { message: \"Multiselect test passed\" };"
    }
})

# End node
flow['nodes'].append({
    "id": "end1",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End"},
    "inputs": {}
})

# Terminate node
flow['nodes'].append({
    "id": "terminateFailed",
    "type": "core.logic.terminate",
    "typeVersion": "1.0",
    "display": {"label": "Multiselect test failed"},
    "inputs": {}
})

# --- Wire edges ---
flow['edges'] = [
    {"id": "e1", "sourceNodeId": "start",          "sourcePortId": "output", "targetNodeId": "createContact1",  "targetPort": "input"},
    {"id": "e2", "sourceNodeId": "createContact1",  "sourcePortId": "output", "targetNodeId": "checkSuccess",    "targetPort": "input"},
    {"id": "e3", "sourceNodeId": "checkSuccess",    "sourcePortId": "true",   "targetNodeId": "logPassed",       "targetPort": "input"},
    {"id": "e4", "sourceNodeId": "checkSuccess",    "sourcePortId": "false",  "targetNodeId": "terminateFailed", "targetPort": "input"},
    {"id": "e5", "sourceNodeId": "logPassed",       "sourcePortId": "success","targetNodeId": "end1",            "targetPort": "input"},
]

# --- Add definitions ---
flow['definitions'].append(def_map['decision'])
flow['definitions'].append(def_map['script'])
flow['definitions'].append(def_map['end'])
flow['definitions'].append(def_map['terminate'])

# --- Add variables.nodes entries for new data-producing nodes ---
flow['variables']['nodes'].append({
    "id": "logPassed.output",
    "type": "object",
    "description": "The return value of the script",
    "binding": {"nodeId": "logPassed", "outputId": "output"}
})
flow['variables']['nodes'].append({
    "id": "checkSuccess.matchedCase",
    "type": "string",
    "description": "The label of the matched branch",
    "binding": {"nodeId": "checkSuccess", "outputId": "matchedCase"}
})
flow['variables']['nodes'].append({
    "id": "checkSuccess.matchedCaseId",
    "type": "string",
    "description": "The branch that was taken",
    "binding": {"nodeId": "checkSuccess", "outputId": "matchedCaseId"}
})

# --- Layout placeholder entries ---
flow['layout']['nodes']['checkSuccess']    = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow['layout']['nodes']['logPassed']       = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow['layout']['nodes']['end1']            = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow['layout']['nodes']['terminateFailed'] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

with open('/work/output/artifacts/skill-flow-ipe-multiselect/MultiselectTest/MultiselectTest/MultiselectTest.flow', 'w') as fp:
    json.dump(flow, fp, indent=2)
print("Written OK")
EOF

